const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");
const crypto = require("node:crypto");
const {spawnSync} = require("node:child_process");
const {fileURLToPath,pathToFileURL} = require("node:url");
const root = process.cwd();
const plan = JSON.parse(fs.readFileSync("docs/phase-plans/Phase001.json"));
const modulePath = path.resolve("docs/phase-plans/complete-phase001.mjs");
const source = fs.readFileSync(modulePath,"utf8").replace(/^import .*;\r?$/gm, "").replaceAll("import.meta.url", "__moduleUrl");
function probe(name, files, withReview) {
  const overlay = new Map(Object.entries(files).map(([p,b])=>[path.resolve(p),Buffer.from(b)]));
  const output = [];
  const fakeProcess = {argv:["node",modulePath,...(withReview?[]:["--without-review"])],exitCode:0};
  const proxyFs = {...fs,readFileSync(p,...args){const b=overlay.get(path.resolve(p));return b ?? fs.readFileSync(p,...args);},writeFileSync(){throw new Error("WRITE_FORBIDDEN");},mkdirSync(){throw new Error("WRITE_FORBIDDEN");}};
  vm.runInNewContext(source,{assert:require("node:assert/strict"),fs:proxyFs,path,createHash:crypto.createHash,spawnSync,fileURLToPath,__moduleUrl:pathToFileURL(modulePath).href,process:fakeProcess,console:{log(v){output.push(v);},error(v){output.push(v);}},Buffer},{timeout:10000});
  console.log(JSON.stringify({probe:name,inMemoryOnly:true,exitCode:fakeProcess.exitCode,output}));
}
probe("unmodified-nine-report-audit",{},false);
const emptySources={};
for(const c of plan.cases){const r=JSON.parse(fs.readFileSync(c.outputPath));r.sourceHashes={};emptySources[c.outputPath]=JSON.stringify(r)+"\n";}
emptySources["docs/phase-plans/verify-phase001.mjs"]=fs.readFileSync("docs/phase-plans/verify-phase001.mjs","utf8")+"\n// IN_MEMORY_STALE_TESTED_SOURCE_PROBE\n";
probe("empty-source-manifests-allow-changed-runner",emptySources,false);
const reviewPath="docs/evidence/attempts/Phase001/"+plan.attemptId+"/review.json";
const falseReview={phase:1,attemptId:plan.attemptId,planPath:"docs/phase-plans/Phase001.json",planHash:crypto.createHash("sha256").update(fs.readFileSync("docs/phase-plans/Phase001.json")).digest("hex"),decision:"PASS",reviewerRunId:"IN_MEMORY_NEGATIVE_FIXTURE",contextId:process.env.CODEX_SESSION_ID,generatedBy:process.env.CODEX_SESSION_ID,runnerIdentity:{kind:"SYNTHETIC_PROTOCOL_FIXTURE_NOT_AGENT_REVIEW",implementationAuthored:false},issues:[],dispositions:[],sourceHashes:{},reportHashes:{}};
probe("synthetic-review-and-empty-bindings-accepted",{[reviewPath]:JSON.stringify(falseReview)+"\n"},true);
